tool_use_result.originalFile:
/**
 * Alert Analytics & Incident Grouping Engine
 * 
 * Provides:
 * 1. Time-series analytics — alert frequency by type over 7/30 day windows
 * 2. Summary statistics — total alerts, most frequent type, peak hour, avg acknowledgment time
 * 3. Incident grouping — deduplicates same-type alerts within a time window into incidents
 * 4. Incident lifecycle — open → acknowledged → resolved with notes
 */

import { createLogger } from '../_core/logger';
import { getDb } from '../db';
import { geometryAlertHistory, alertIncidents } from '../../drizzle/schema';
import { eq, and, gte, lte, desc, sql, count, avg, inArray } from 'drizzle-orm';

const log = createLogger('alert-analytics');

// ─── Types ────────────────────────────────────────────────────────

export interface AlertFrequencyPoint {
  date: string;       // YYYY-MM-DD
  alertType: string;
  count: number;
}

export interface AlertTrend {
  alertType: string;
  points: { date: string; count: number }[];
  total: number;
}

export interface AlertSummaryStats {
  totalAlerts: number;
  totalUnacknowledged: number;
  totalIncidents: number;
  openIncidents: number;
  mostFrequentType: string | null;
  mostFrequentTypeCount: number;
  peakHour: number | null;       // 0-23
  peakHourCount: number;
  avgAcknowledgeTimeMs: number | null;
  alertsByType: { alertType: string; count: number; percentage: number }[];
  alertsBySeverity: { severity: string; count: number }[];
}

export interface IncidentSummary {
  incidentId: string;
  alertType: string;
  sessionId: string | null;
  severity: string;
  status: string;
  alertCount: number;
  firstAlertAt: number;
  lastAlertAt: number;
  peakValue: number | null;
  peakThreshold: number | null;
  resolvedAt: number | null;
  resolvedBy: string | null;
  resolutionNotes: string | null;
  durationMs: number;
}

export interface IncidentDetail extends IncidentSummary {
  alerts: {
    alertId: string;
    severity: string;
    value: number | null;
    threshold: number | null;
    message: string | null;
    firedAt: number;
    acknowledged: boolean;
  }[];
}

// ─── Incident Grouping Config ─────────────────────────────────────

/** Time window for grouping alerts into incidents (5 minutes) */
const INCIDENT_GROUPING_WINDOW_MS = 5 * 60 * 1000;

/** Zeroed stats, returned when the database is unavailable or a query fails. */
function emptySummaryStats(): AlertSummaryStats {
  return {
    totalAlerts: 0,
    totalUnacknowledged: 0,
    totalIncidents: 0,
    openIncidents: 0,
    mostFrequentType: null,
    mostFrequentTypeCount: 0,
    peakHour: null,
    peakHourCount: 0,
    avgAcknowledgeTimeMs: null,
    alertsByType: [],
    alertsBySeverity: [],
  };
}

// ─── Analytics Queries ────────────────────────────────────────────

/**
 * Get alert frequency by type over a date range, bucketed by day.
 */
export async function getAlertFrequencyByType(options: {
  days: number;
  alertTypes?: string[];
}): Promise<AlertTrend[]> {
  try {
    const db = await getDb();
    if (!db) {
      log.warn('Alert frequency query skipped — database not available');
      return [];
    }
    const since = Date.now() - options.days * 24 * 60 * 60 * 1000;

    // Query raw data from alert history
    let query = db.select({
      alertType: geometryAlertHistory.alertType,
      firedAt: geometryAlertHistory.firedAt,
    })
      .from(geometryAlertHistory)
      .where(gte(geometryAlertHistory.firedAt, since));

    const rows = await query;

    // Bucket by day and type
    const buckets = new Map<string, Map<string, number>>();
    const typeTotals = new Map<string, number>();

    for (const row of rows) {
      if (options.alertTypes && options.alertTypes.length > 0) {
        if (!options.alertTypes.includes(row.alertType)) continue;
      }
      const date = new Date(Number(row.firedAt)).toISOString().split('T')[0];
      if (!buckets.has(row.alertType)) buckets.set(row.alertType, new Map());
      const typeBucket = buckets.get(row.alertType)!;
      typeBucket.set(date, (typeBucket.get(date) ?? 0) + 1);
      typeTotals.set(row.alertType, (typeTotals.get(row.alertType) ?? 0) + 1);
    }

    // Generate date range
    const dates: string[] = [];
    for (let i = options.days - 1; i >= 0; i--) {
      const d = new Date(Date.now() - i * 24 * 60 * 60 * 1000);
      dates.push(d.toISOString().split('T')[0]);
    }

    // Build trends
    const trends: AlertTrend[] = [];
    for (const [alertType, typeBucket] of buckets) {
      trends.push({
        alertType,
        total: typeTotals.get(alertType) ?? 0,
        points: dates.map(date => ({
          date,
          count: typeBucket.get(date) ?? 0,
        })),
      });
    }

    // Sort by total descending
    trends.sort((a, b) => b.total - a.total);
    return trends;
  } catch (err) {
    log.error({ error: err instanceof Error ? err.message : String(err) }, 'Failed to get alert frequency');
    return [];
  }
}

/**
 * Get comprehensive alert summary statistics.
 */
export async function getAlertSummaryStats(days: number = 30): Promise<AlertSummaryStats> {
  try {
    const db = await getDb();
    if (!db) {
      log.warn('Alert summary stats skipped — database not available');
      return emptySummaryStats();
    }
    const since = Date.now() - days * 24 * 60 * 60 * 1000;

    // Total alerts and unacknowledged
    const [totals] = await db.select({
      total: count(),
      unacknowledged: sql<number>`SUM(CASE WHEN ${geometryAlertHistory.acknowledged} = false THEN 1 ELSE 0 END)`,
    })
      .from(geometryAlertHistory)
      .where(gte(geometryAlertHistory.firedAt, since));

    // Total incidents and open incidents
    const [incidentTotals] = await db.select({
      total: count(),
      open: sql<number>`SUM(CASE WHEN ${alertIncidents.status} = 'open' THEN 1 ELSE 0 END)`,
    })
      .from(alertIncidents)
      .where(gte(alertIncidents.firstAlertAt, since));

    // Alerts by type
    const byType = await db.select({
      alertType: geometryAlertHistory.alertType,
      cnt: count(),
    })
      .from(geometryAlertHistory)
      .where(gte(geometryAlertHistory.firedAt, since))
      .groupBy(geometryAlertHistory.alertType)
      .orderBy(desc(count()));

    // Alerts by severity
    const bySeverity = await db.select({
      severity: geometryAlertHistory.severity,
      cnt: count(),
    })
      .from(geometryAlertHistory)
      .where(gte(geometryAlertHistory.firedAt, since))
      .groupBy(geometryAlertHistory.severity);

    // Peak hour analysis
    const allAlerts = await db.select({
      firedAt: geometryAlertHistory.firedAt,
    })
      .from(geometryAlertHistory)
      .where(gte(geometryAlertHistory.firedAt, since));

    const hourCounts = new Array(24).fill(0);
    for (const alert of allAlerts) {
      const hour = new Date(Number(alert.firedAt)).getHours();
      hourCounts[hour]++;
    }
    let peakHour: number | null = null;
    let peakHourCount = 0;
    for (let h = 0; h < 24; h++) {
      if (hourCounts[h] > peakHourCount) {
        peakHour = h;
        peakHourCount = hourCounts[h];
      }
    }

    // Average acknowledge time
    const ackAlerts = await db.select({
      firedAt: geometryAlertHistory.firedAt,
      acknowledgedAt: geometryAlertHistory.acknowledgedAt,
    })
      .from(geometryAlertHistory)
      .where(and(
        gte(geometryAlertHistory.firedAt, since),
        eq(geometryAlertHistory.acknowledged, true),
      ));

    let avgAckTime: number | null = null;
    if (ackAlerts.length > 0) {
      const totalAckTime = ackAlerts.reduce((sum, a) => {
        if (a.acknowledgedAt) {
          return sum + (Number(a.acknowledgedAt) - Number(a.firedAt));
        }
        return sum;
      }, 0);
      avgAckTime = Math.round(totalAckTime / ackAlerts.length);
    }

    const totalAlerts = totals?.total ?? 0;
    const mostFrequent = byType[0];

    return {
      totalAlerts,
      totalUnacknowledged: Number(totals?.unacknowledged ?? 0),
      totalIncidents: incidentTotals?.total ?? 0,
      openIncidents: Number(incidentTotals?.open ?? 0),
      mostFrequentType: mostFrequent?.alertType ?? null,
      mostFrequentTypeCount: mostFrequent?.cnt ?? 0,
      peakHour,
      peakHourCount,
      avgAcknowledgeTimeMs: avgAckTime,
      alertsByType: byType.map(t => ({
        alertType: t.alertType,
        count: t.cnt,
        percentage: totalAlerts > 0 ? Math.round((t.cnt / totalAlerts) * 100) : 0,
      })),
      alertsBySeverity: bySeverity.map(s => ({
        severity: s.severity,
        count: s.cnt,
      })),
    };
  } catch (err) {
    log.error({ error: err instanceof Error ? err.message : String(err) }, 'Failed to get alert summary stats');
    return emptySummaryStats();
  }
}

// ─── Incident Grouping ───────────────────────────────────────────

/**
 * Group a new alert into an existing open incident or create a new one.
 * Called after each alert is fired.
 */
export async function groupAlertIntoIncident(alert: {
  alertId: string;
  alertType: string;
  severity: 'warning' | 'critical';
  sessionId?: string | null;
  value?: number | null;
  threshold?: number | null;
  firedAt: number;
}): Promise<{ incidentId: string; isNew: boolean; alertCount: number }> {
  try {
    const db = await getDb();
    if (!db) {
      log.warn({ alertType: alert.alertType }, 'Incident grouping skipped — database not available');
      // Return a synthetic incident ID so the alert isn't lost
      return { incidentId: `inc_unavailable_${Date.now()}`, isNew: true, alertCount: 1 };
    }
    const windowStart = alert.firedAt - INCIDENT_GROUPING_WINDOW_MS;

    // Find an existing open incident of the same type within the grouping window
    const existingIncidents = await db.select()
      .from(alertIncidents)
      .where(and(
        eq(alertIncidents.alertType, alert.alertType),
        eq(alertIncidents.status, 'open'),
        gte(alertIncidents.lastAlertAt, windowStart),
      ))
      .orderBy(desc(alertIncidents.lastAlertAt))
      .limit(1);

    if (existingIncidents.length > 0) {
      const incident = existingIncidents[0];
      const newCount = incident.alertCount + 1;
      const newPeakValue = (alert.value !== null && alert.value !== undefined)
        ? Math.max(incident.peakValue ?? 0, alert.value)
        : incident.peakValue;

      // Escalate severity if new alert is more severe
      const newSeverity = alert.severity === 'critical' ? 'critical' : incident.severity;

      await db.update(alertIncidents)
        .set({
          alertCount: newCount,
          lastAlertAt: alert.firedAt,
          lastAlertId: alert.alertId,
          peakValue: newPeakValue,
          severity: newSeverity,
        })
        .where(eq(alertIncidents.id, incident.id));

      log.info({
        incidentId: incident.incidentId,
        alertCount: newCount,
        alertType: alert.alertType,
      }, 'Alert grouped into existing incident');

      return { incidentId: incident.incidentId, isNew: false, alertCount: newCount };
    }

    // Create a new incident
    const incidentId = `inc_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    await db.insert(alertIncidents).values({
      incidentId,
      alertType: alert.alertType,
      sessionId: alert.sessionId ?? null,
      severity: alert.severity,
      status: 'open',
      alertCount: 1,
      firstAlertAt: alert.firedAt,
      lastAlertAt: alert.firedAt,
      firstAlertId: alert.alertId,
      lastAlertId: alert.alertId,
      peakValue: alert.value ?? null,
      peakThreshold: alert.threshold ?? null,
    });

    log.info({ incidentId, alertType: alert.alertType }, 'New incident created');
    return { incidentId, isNew: true, alertCount: 1 };
  } catch (err) {
    log.error({ error: err instanceof Error ? err.message : String(err) }, 'Failed to group alert into incident');
    // Return a synthetic incident ID so the alert isn't lost
    return { incidentId: `inc_error_${Date.now()}`, isNew: true, alertCount: 1 };
  }
}

// ─── Incident Queries ─────────────────────────────────────────────

/**
 * Get incidents with optional filtering.
 */
export async function getIncidents(options?: {
  status?: 'open' | 'acknowledged' | 'resolved';
  alertType?: string;
  severity?: 'warning' | 'critical';
  days?: number;
  limit?: number;
  offset?: number;
}): Promise<{ incidents: IncidentSummary[]; total: number }> {
  try {
    const db = await getDb();
    if (!db) {
      log.warn('Incident query skipped — database not available');
      return { incidents: [], total: 0 };
    }
    const limit = options?.limit ?? 50;
    const offset = options?.offset ?? 0;
    const conditions: any[] = [];

    if (options?.status) {
      conditions.push(eq(alertIncidents.status, options.status));
    }
    if (options?.alertType) {
      conditions.push(eq(alertIncidents.alertType, options.alertType));
    }
    if (options?.severity) {
      conditions.push(eq(alertIncidents.severity, options.severity));
    }
    if (options?.days) {
      const since = Date.now() - options.days * 24 * 60 * 60 * 1000;
      conditions.push(gte(alertIncidents.firstAlertAt, since));
    }

    const where = conditions.length > 0 ? and(...conditions) : undefined;

    const [countResult] = await db.select({ total: count() })
      .from(alertIncidents)
      .where(where);

    const rows = await db.select()
      .from(alertIncidents)
      .where(where)
      .orderBy(desc(alertIncidents.lastAlertAt))
      .limit(limit)
      .offset(offset);

    const incidents: IncidentSummary[] = rows.map(r => ({
      incidentId: r.incidentId,
      alertType: r.alertType,
      sessionId: r.sessionId,
      severity: r.severity,
      status: r.status,
      alertCount: r.alertCount,
      firstAlertAt: Number(r.firstAlertAt),
      lastAlertAt: Number(r.lastAlertAt),
      peakValue: r.peakValue,
      peakThreshold: r.peakThreshold,
      resolvedAt: r.resolvedAt ? Number(r.resolvedAt) : null,
      resolvedBy: r.resolvedBy,
      resolutionNotes: r.resolutionNotes,
      durationMs: Number(r.lastAlertAt) - Number(r.firstAlertAt),
    }));

    return { incidents, total: countResult?.total ?? 0 };
  } catch (err) {
    log.error({ error: err instanceof Error ? err.message : String(err) }, 'Failed to get incidents');
    return { incidents: [], total: 0 };
  }
}

/**
 * Get incident detail with all grouped alerts.
 */
export async function getIncidentDetail(incidentId: string): Promise<IncidentDetail | null> {
  try {
    const db = await getDb();
    if (!db) {
      log.warn({ incidentId }, 'Incident detail lookup skipped — database not available');
      return null;
    }

    const [incident] = await db.select()
      .from(alertIncidents)
      .where(eq(alertIncidents.incidentId, incidentId));

    if (!incident) return null;

    // Get all alerts within the incident's time window for the same type
    const alerts = await db.select({
      alertId: geometryAlertHistory.alertId,
      severity: geometryAlertHistory.severity,
      value: geometryAlertHistory.value,
      threshold: geometryAlertHistory.threshold,
      message: geometryAlertHistory.message,
      firedAt: geometryAlertHistory.firedAt,
      acknowledged: geometryAlertHistory.acknowledged,
    })
      .from(geometryAlertHistory)
      .where(and(
        eq(geometryAlertHistory.alertType, incident.alertType),
        gte(geometryAlertHistory.firedAt, incident.firstAlertAt),
        lte(geometryAlertHistory.firedAt, incident.lastAlertAt),
      ))
      .orderBy(desc(geometryAlertHistory.firedAt));

    return {
      incidentId: incident.incidentId,
      alertType: incident.alertType,
      sessionId: incident.sessionId,
      severity: incident.severity,
      status: incident.status,
      alertCount: incident.alertCount,
      firstAlertAt: Number(incident.firstAlertAt),
      lastAlertAt: Number(incident.lastAlertAt),
      peakValue: incident.peakValue,
      peakThreshold: incident.peakThreshold,
      resolvedAt: incident.resolvedAt ? Number(incident.resolvedAt) : null,
      resolvedBy: incident.resolvedBy,
      resolutionNotes: incident.resolutionNotes,
      durationMs: Number(incident.lastAlertAt) - Number(incident.firstAlertAt),
      alerts: alerts.map(a => ({
        alertId: a.alertId,
        severity: a.severity,
        value: a.value,
        threshold: a.threshold,
        message: a.message,
        firedAt: Number(a.firedAt),
        acknowledged: a.acknowledged,
      })),
    };
  } catch (err) {
    log.error({ error: err instanceof Error ? err.message : String(err) }, 'Failed to get incident detail');
    return null;
  }
}

/**
 * Resolve an incident with notes.
 */
export async function resolveIncident(
  incidentId: string,
  resolvedBy: string,
  notes?: string,
): Promise<boolean> {
  try {
    const db = await getDb();
    await db.update(alertIncidents)
      .set({
        status: 'resolved',
        resolvedAt: Date.now(),
        resolvedBy,
        resolutionNotes: notes ?? null,
      })
      .where(eq(alertIncidents.incidentId, incidentId));

    log.info({ incidentId, resolvedBy }, 'Incident resolved');
    return true;
  } catch (err) {
    log.error({ error: err instanceof Error ? err.message : String(err) }, 'Failed to resolve incident');
    return false;
  }
}

/**
 * Acknowledge an incident (intermediate state before resolution).
 */
export async function acknowledgeIncident(
  incidentId: string,
): Promise<boolean> {
  try {
    const db = await getDb();
    await db.update(alertIncidents)
      .set({ status: 'acknowledged' })
      .where(eq(alertIncidents.incidentId, incidentId));

    log.info({ incidentId }, 'Incident acknowledged');
    return true;
  } catch (err) {
    log.error({ error: err instanceof Error ? err.message : String(err) }, 'Failed to acknowledge incident');
    return false;
  }
}

// ─── Exports for testing ──────────────────────────────────────────

export const INCIDENT_GROUPING_WINDOW = INCIDENT_GROUPING_WINDOW_MS;

